window.PRELOADED_ASSIGNMENTS = [{"id": "MIS-ASSIGN-W01-Q01", "week": 1, "question_num": 1, "question": "What is the primary goal of MIS?", "option_a": "Increase hardware sales", "option_b": "Generate raw data", "option_c": "Transform data into useful information for decision-making", "option_d": "Replace managers", "correct_answer": "C", "topic": "Primary Goals of MIS", "solution": "The foundational definition of a Management Information System (MIS) is to collect, process, store, and transform raw facts (data) into meaningful, structured information that supports organizational decision-making, operational coordination, and managerial control.", "source_pdf_page": 1}, {"id": "MIS-ASSIGN-W01-Q02", "week": 1, "question_num": 2, "question": "Which of the following represents the correct hierarchy?", "option_a": "Wisdom → Knowledge → Information → Data", "option_b": "Data → Information → Knowledge → Wisdom", "option_c": "Information → Data → Wisdom → Knowledge", "option_d": "Knowledge → Data → Information → Wisdom", "correct_answer": "B", "topic": "DIKW Pyramid Hierarchy", "solution": "The standard DIKW hierarchy progresses upwards from raw data (unstructured facts) → information (contextualized and structured data) → knowledge (synthesized information applied to solve problems) → wisdom (the evaluated understanding and judgment of when and how to apply knowledge).", "source_pdf_page": 1}, {"id": "MIS-ASSIGN-W01-Q03", "week": 1, "question_num": 3, "question": "Data can best be described as:", "option_a": "Processed facts", "option_b": "Meaningful insights", "option_c": "Raw facts and figures", "option_d": "Strategic decisions", "correct_answer": "C", "topic": "Definition of Data", "solution": "In information systems, data is explicitly defined as streams of raw facts and figures representing events occurring in organizations or the physical environment before they have been organized and arranged into a form that people can understand and use.", "source_pdf_page": 1}, {"id": "MIS-ASSIGN-W01-Q04", "week": 1, "question_num": 4, "question": "Information is:", "option_a": "Unprocessed data", "option_b": "Data arranged in a meaningful form", "option_c": "A collection of hardware devices", "option_d": "Organizational culture", "correct_answer": "B", "topic": "Definition of Information", "solution": "Information represents data that has been shaped into a meaningful and useful context for human beings, allowing managers to interpret patterns, make informed decisions, and coordinate business actions.", "source_pdf_page": 2}, {"id": "MIS-ASSIGN-W01-Q05", "week": 1, "question_num": 5, "question": "Which activity captures raw data in an information system?", "option_a": "Processing", "option_b": "Feedback", "option_c": "Input", "option_d": "Output", "correct_answer": "C", "topic": "Information System Activities (Input)", "solution": "Input is the activity of capturing or collecting raw data from within the organization or from its external environment for introduction into an information system.", "source_pdf_page": 2}, {"id": "MIS-ASSIGN-W01-Q06", "week": 1, "question_num": 6, "question": "Which activity converts raw data into meaningful information?", "option_a": "Feedback", "option_b": "Processing", "option_c": "Input", "option_d": "Distribution", "correct_answer": "B", "topic": "Information System Activities (Processing)", "solution": "Processing converts raw input into meaningful information through calculations, comparisons, sorting, summarizing, and data manipulation.", "source_pdf_page": 2}, {"id": "MIS-ASSIGN-W01-Q07", "week": 1, "question_num": 7, "question": "The output of an information system is primarily used for:", "option_a": "Data collection", "option_b": "Data storage", "option_c": "Decision-making and actions", "option_d": "Hardware maintenance", "correct_answer": "C", "topic": "Information System Activities (Output)", "solution": "Output transfers the processed information to the people who will use it or to the activities for which it will be used, primarily for managerial decision-making and operational execution.", "source_pdf_page": 2}, {"id": "MIS-ASSIGN-W01-Q08", "week": 1, "question_num": 8, "question": "Feedback in an information system is used to:", "option_a": "Increase storage capacity", "option_b": "Correct or evaluate inputs", "option_c": "Replace processing", "option_d": "Eliminate outputs", "correct_answer": "B", "topic": "Information System Feedback Mechanism", "solution": "Feedback is output that is returned to appropriate members of the organization to help them evaluate or correct the input stage, ensuring system accuracy and adaptive operational control.", "source_pdf_page": 2}, {"id": "MIS-ASSIGN-W01-Q09", "week": 1, "question_num": 9, "question": "Computers and software are considered:", "option_a": "Complete information systems", "option_b": "Organizational assets", "option_c": "Technical foundations of information systems", "option_d": "Decision makers", "correct_answer": "C", "topic": "IS Dimensions & Technical Foundation", "solution": "Computers and software constitute information technology (IT), which provides the technical foundation, tools, and infrastructure through which an organization builds its broader Information System (IS).", "source_pdf_page": 3}, {"id": "MIS-ASSIGN-W01-Q10", "week": 1, "question_num": 10, "question": "Which technology trend is highlighted as transforming business?", "option_a": "Typewriters", "option_b": "Mobile digital platforms", "option_c": "Telegraph systems", "option_d": "Mechanical calculators", "correct_answer": "B", "topic": "Emerging Information Technology Trends", "solution": "Mobile digital platforms, cloud computing, and big data analytics are the major contemporary technology trends transforming modern digital firms and business workflows.", "source_pdf_page": 3}, {"id": "MIS-ASSIGN-W02-Q01", "week": 2, "question_num": 1, "question": "What is the smallest unit of data a computer can handle?", "option_a": "Byte", "option_b": "Field", "option_c": "Bit", "option_d": "Record", "correct_answer": "C", "topic": "Data Hierarchy Fundamentals", "solution": "A bit (binary digit) represents the smallest unit of data in computing, capable of storing a binary state of either 0 or 1. Eight bits group together to form a byte.", "source_pdf_page": 4}, {"id": "MIS-ASSIGN-W02-Q02", "week": 2, "question_num": 2, "question": "A collection of related files is known as:", "option_a": "Record", "option_b": "Field", "option_c": "Database", "option_d": "Byte", "correct_answer": "C", "topic": "Data Hierarchy & Database Definition", "solution": "In the data hierarchy, bits form bytes (characters), bytes form fields, fields form records, records form files (tables), and a group of related files forms a database.", "source_pdf_page": 4}, {"id": "MIS-ASSIGN-W02-Q03", "week": 2, "question_num": 3, "question": "An entity can be best described as:", "option_a": "A software package", "option_b": "A person, place, or thing about which data is stored", "option_c": "A collection of records", "option_d": "A database query", "correct_answer": "B", "topic": "Entity-Relationship Concepts", "solution": "An entity is any person, place, thing, or event in the real world about which an organization maintains stored information (e.g., CUSTOMER, PRODUCT, ORDER).", "source_pdf_page": 4}, {"id": "MIS-ASSIGN-W02-Q04", "week": 2, "question_num": 4, "question": "Which of the following is an attribute of a STUDENT entity?", "option_a": "Database", "option_b": "Grade", "option_c": "Folder", "option_d": "File", "correct_answer": "B", "topic": "Entity Attributes", "solution": "Attributes are specific characteristics or properties describing an entity. For a STUDENT entity, Grade, Student_ID, Name, and Major are valid attributes.", "source_pdf_page": 4}, {"id": "MIS-ASSIGN-W02-Q05", "week": 2, "question_num": 5, "question": "Data redundancy refers to:", "option_a": "Missing data", "option_b": "Duplicate data stored in multiple files", "option_c": "Incorrect data entry", "option_d": "Unauthorized access", "correct_answer": "B", "topic": "Traditional File Environment Problems", "solution": "Data redundancy is the presence of duplicate data in multiple data files, so that the same data values are stored in more than one place, wasting storage and creating inconsistency.", "source_pdf_page": 5}, {"id": "MIS-ASSIGN-W02-Q06", "week": 2, "question_num": 6, "question": "Data inconsistency occurs when:", "option_a": "Data is encrypted", "option_b": "Data is stored in a warehouse", "option_c": "Same attribute has different values", "option_d": "Data is normalized", "correct_answer": "C", "topic": "Data Inconsistency", "solution": "Data inconsistency exists when different copies of the same data do not agree with each other—such as when a customer address is updated in one department system but remains outdated in another.", "source_pdf_page": 5}, {"id": "MIS-ASSIGN-W02-Q07", "week": 2, "question_num": 7, "question": "A primary key is used for:", "option_a": "Data backup", "option_b": "Data compression", "option_c": "Unique identification of records", "option_d": "Data mining", "correct_answer": "C", "topic": "Relational Database Keys", "solution": "A primary key is a field (or column) in a relational table that uniquely identifies each record (row) so that no two rows can share the exact same primary key value.", "source_pdf_page": 5}, {"id": "MIS-ASSIGN-W02-Q08", "week": 2, "question_num": 8, "question": "A DBMS acts as:", "option_a": "A spreadsheet tool", "option_b": "An interface between applications and databases", "option_c": "A programming language", "option_d": "A web browser", "correct_answer": "B", "topic": "Role of Database Management Systems", "solution": "A Database Management System (DBMS) is software that acts as an interface between application programs and the physical data files, relieving programmers from having to understand physical data storage layouts.", "source_pdf_page": 5}, {"id": "MIS-ASSIGN-W02-Q09", "week": 2, "question_num": 9, "question": "One major advantage of DBMS is:", "option_a": "Increased redundancy", "option_b": "Reduces inconsistency", "option_c": "Reduced storage capacity", "option_d": "Decentralized security", "correct_answer": "B", "topic": "Benefits of Relational DBMS", "solution": "A DBMS centralizes data management, minimizes data redundancy, eliminates data inconsistency, and enforces unified access security and integrity constraints across the organization.", "source_pdf_page": 5}, {"id": "MIS-ASSIGN-W02-Q10", "week": 2, "question_num": 10, "question": "Which is a major BI tool?", "option_a": "OLAP", "option_b": "Compiler", "option_c": "Antivirus", "option_d": "Browser", "correct_answer": "A", "topic": "Business Intelligence (BI) Tools", "solution": "Online Analytical Processing (OLAP) is a cornerstone Business Intelligence capability that enables multidimensional analysis of consolidated corporate data across time, product, and regional hierarchies.", "source_pdf_page": 6}, {"id": "MIS-ASSIGN-W03-Q01", "week": 3, "question_num": 1, "question": "SAP stands for:", "option_a": "Systems Applications & Products in Data Processing", "option_b": "Standard Applications Processing", "option_c": "Systems and Products Platform", "option_d": "Software Applications Processing", "correct_answer": "A", "topic": "ERP Enterprise Software (SAP)", "solution": "SAP is the global standard in ERP and stands for Systems, Applications, and Products in Data Processing (originally Systeme, Anwendungen und Produkte in der Datenverarbeitung).", "source_pdf_page": 7}, {"id": "MIS-ASSIGN-W03-Q02", "week": 3, "question_num": 2, "question": "SAP R/3 follows:", "option_a": "Two-tier architecture", "option_b": "Four-tier architecture", "option_c": "Three-tier architecture", "option_d": "Single-tier architecture", "correct_answer": "C", "topic": "SAP R/3 System Architecture", "solution": "The '3' in SAP R/3 explicitly denotes its client/server 3-tier architecture, cleanly separating the Database Layer, Application Layer, and Presentation (GUI) Layer.", "source_pdf_page": 7}, {"id": "MIS-ASSIGN-W03-Q03", "week": 3, "question_num": 3, "question": "In SAP R/3, GUI components belong to:", "option_a": "Database layer", "option_b": "Application layer", "option_c": "Presentation layer", "option_d": "Middleware layer", "correct_answer": "C", "topic": "Three-Tier Client/Server Architecture", "solution": "The Graphical User Interface (SAP GUI) runs at the Presentation Layer on client PCs or web browsers to display data and capture user input.", "source_pdf_page": 7}, {"id": "MIS-ASSIGN-W03-Q04", "week": 3, "question_num": 4, "question": "A key business benefit expected from ERP is:", "option_a": "Increased inventory levels", "option_b": "Integrated supply chain management", "option_c": "Increased manual effort", "option_d": "More isolated systems", "correct_answer": "B", "topic": "Business Value of ERP", "solution": "ERP integrates disparate business functions into a single unified software system and central database, enabling seamless end-to-end supply chain coordination and rapid cross-functional data sharing.", "source_pdf_page": 7}, {"id": "MIS-ASSIGN-W03-Q05", "week": 3, "question_num": 5, "question": "ERP helps reduce:", "option_a": "Order-to-cash cycle time", "option_b": "Data availability", "option_c": "Productivity", "option_d": "Automation", "correct_answer": "A", "topic": "ERP Operational Efficiencies", "solution": "By eliminating departmental silos and automating inter-departmental handoffs, ERP dramatically accelerates the 'order-to-cash' cycle—the total time taken from receiving a customer order to collecting payment.", "source_pdf_page": 8}, {"id": "MIS-ASSIGN-W03-Q06", "week": 3, "question_num": 6, "question": "ERP facilitates:", "option_a": "Business Process Reengineering (BPR)", "option_b": "Data duplication", "option_c": "Information silos", "option_d": "Stand-alone processing", "correct_answer": "A", "topic": "ERP and Business Process Reengineering", "solution": "ERP implementations require organizations to examine and often radically redesign their operational workflows to align with standardized best-practice industry processes (Business Process Reengineering - BPR).", "source_pdf_page": 8}, {"id": "MIS-ASSIGN-W03-Q07", "week": 3, "question_num": 7, "question": "ERP affects:", "option_a": "Business processes", "option_b": "Company culture", "option_c": "Employee skills", "option_d": "All of the above", "correct_answer": "D", "topic": "Organizational Impact of ERP", "solution": "ERP adoption is not merely a software upgrade; it is an organizational transformation that fundamentally impacts business processes, organizational culture, job roles, and employee technological competencies.", "source_pdf_page": 8}, {"id": "MIS-ASSIGN-W03-Q08", "week": 3, "question_num": 8, "question": "ERP can reduce costs through:", "option_a": "Better supplier management", "option_b": "Increased redundancy", "option_c": "More manual work", "option_d": "Separate purchasing systems", "correct_answer": "A", "topic": "ERP Cost Reduction Mechanisms", "solution": "ERP provides company-wide visibility into purchasing, allowing enterprises to aggregate orders, negotiate volume discounts, and optimize supplier contracts and vendor performance.", "source_pdf_page": 8}, {"id": "MIS-ASSIGN-W03-Q09", "week": 3, "question_num": 9, "question": "A common reason for ERP project risk is:", "option_a": "Strong top management support", "option_b": "Inexperienced core team", "option_c": "Stable requirements", "option_d": "High computer literacy", "correct_answer": "B", "topic": "ERP Implementation Risks", "solution": "ERP implementation failures typically stem from inexperienced project management teams, lack of user training, employee resistance to change, and inadequate executive championship.", "source_pdf_page": 8}, {"id": "MIS-ASSIGN-W03-Q10", "week": 3, "question_num": 10, "question": "A limitation of traditional MRP was:", "option_a": "Lack of planning capability", "option_b": "Ignoring available capacity during planning", "option_c": "Too much HR integration", "option_d": "Real-time collaboration", "correct_answer": "B", "topic": "Evolution from MRP to MRP II and ERP", "solution": "Traditional Material Requirements Planning (MRP I) operated on infinite capacity assumptions, generating schedules based on inventory requirements while completely ignoring whether machine and labor capacity actually existed.", "source_pdf_page": 9}, {"id": "MIS-ASSIGN-W04-Q01", "week": 4, "question_num": 1, "question": "SCM involves which two major flows?", "option_a": "Product and profit flow", "option_b": "Material flow and information flow", "option_c": "Cash flow and tax flow", "option_d": "Labor flow and energy flow", "correct_answer": "B", "topic": "Supply Chain Management Flows", "solution": "Supply Chain Management coordinates two fundamental streams: the physical flow of materials/goods from suppliers to consumers, and the bidirectional flow of information (demands, orders, shipments, and inventory states).", "source_pdf_page": 10}, {"id": "MIS-ASSIGN-W04-Q02", "week": 4, "question_num": 2, "question": "A supply chain is best described as a:", "option_a": "Single manufacturing unit", "option_b": "Distribution warehouse", "option_c": "Network of resources, organizations, technologies, and processes", "option_d": "Marketing department", "correct_answer": "C", "topic": "Supply Chain Definition", "solution": "A supply chain is a network of organizations and business processes for procuring materials, transforming raw materials into intermediate and finished products, and distributing the finished products to customers.", "source_pdf_page": 10}, {"id": "MIS-ASSIGN-W04-Q03", "week": 4, "question_num": 3, "question": "One method of reducing the bullwhip effect is to:", "option_a": "Increase batch sizes", "option_b": "Improve communication across the supply chain", "option_c": "Reduce information sharing", "option_d": "Increase shortages", "correct_answer": "B", "topic": "Bullwhip Effect Mitigation", "solution": "The bullwhip effect—where demand distortion magnifies upstream—is mitigated by sharing real-time point-of-sale (POS) data, reducing batch sizes, and maintaining transparent collaborative communication across all tiers.", "source_pdf_page": 10}, {"id": "MIS-ASSIGN-W04-Q04", "week": 4, "question_num": 4, "question": "Demand-driven supply chains use a:", "option_a": "Push system", "option_b": "Pull system", "option_c": "Manual system", "option_d": "Forecast-only system", "correct_answer": "B", "topic": "Push vs. Pull Supply Chain Models", "solution": "In a pull-based (demand-driven) model, actual customer orders trigger events in the supply chain. Materials and products are only produced and moved when dictated by real end-consumer consumption.", "source_pdf_page": 10}, {"id": "MIS-ASSIGN-W04-Q05", "week": 4, "question_num": 5, "question": "In a Just-in-Time (JIT) strategy, components arrive:", "option_a": "Months before production", "option_b": "After product delivery", "option_c": "As they are needed", "option_d": "At fixed yearly intervals", "correct_answer": "C", "topic": "Just-in-Time (JIT) Manufacturing", "solution": "A Just-in-Time strategy coordinates supplier deliveries so that raw materials and components arrive at the factory floor precisely at the moment they are needed for production, minimizing holding costs.", "source_pdf_page": 11}, {"id": "MIS-ASSIGN-W04-Q06", "week": 4, "question_num": 6, "question": "Which supply chain consists of suppliers and suppliers' suppliers?", "option_a": "Internal supply chain", "option_b": "Downstream supply chain", "option_c": "Upstream supply chain", "option_d": "Retail supply chain", "correct_answer": "C", "topic": "Upstream Supply Chain Structure", "solution": "The upstream portion of the supply chain includes a company's suppliers, the suppliers' suppliers (Tier 2, Tier 3), and the processes for managing relationships with them.", "source_pdf_page": 11}, {"id": "MIS-ASSIGN-W04-Q07", "week": 4, "question_num": 7, "question": "The downstream supply chain focuses on:", "option_a": "Raw material suppliers", "option_b": "Internal warehouses", "option_c": "Product delivery to customers", "option_d": "Employee management", "correct_answer": "C", "topic": "Downstream Supply Chain Structure", "solution": "The downstream portion of the supply chain consists of the organizations and processes for distributing and delivering finished goods to the final customers.", "source_pdf_page": 11}, {"id": "MIS-ASSIGN-W04-Q08", "week": 4, "question_num": 8, "question": "Internal supply chain activities occur:", "option_a": "Between countries", "option_b": "Inside the factory", "option_c": "Only with customers", "option_d": "Only with suppliers", "correct_answer": "B", "topic": "Internal Supply Chain Processes", "solution": "The internal supply chain encompasses the manufacturing, transformation, assembly, and packaging processes that take place inside the enterprise's own facilities.", "source_pdf_page": 11}, {"id": "MIS-ASSIGN-W04-Q09", "week": 4, "question_num": 9, "question": "The bullwhip effect occurs when:", "option_a": "Inventory is eliminated", "option_b": "Demand information gets distorted along the supply chain", "option_c": "Production exceeds quality standards", "option_d": "Warehouses are automated", "correct_answer": "B", "topic": "Bullwhip Effect Mechanism", "solution": "The bullwhip effect occurs when small fluctuations in retail customer demand become progressively distorted and magnified as information travels back up the supply chain from retailer to distributor to manufacturer.", "source_pdf_page": 11}, {"id": "MIS-ASSIGN-W04-Q10", "week": 4, "question_num": 10, "question": "A push-based model is also known as:", "option_a": "Build-to-order", "option_b": "Build-to-stock", "option_c": "Demand-driven", "option_d": "Pull-based", "correct_answer": "B", "topic": "Push-Based Production Models", "solution": "In a push-based model (build-to-stock), production schedules are based on forecasts or best guesses of demand for products, and products are 'pushed' to customers.", "source_pdf_page": 12}, {"id": "MIS-ASSIGN-W05-Q01", "week": 5, "question_num": 1, "question": "A company manufactures customized industrial machinery only after receiving confirmed customer orders. This production strategy is best classified as:", "option_a": "Make-to-stock", "option_b": "Continuous production", "option_c": "Make-to-order", "option_d": "Batch processing", "correct_answer": "C", "topic": "Make-to-Order Manufacturing Strategy", "solution": "Make-to-Order (MTO) is a production approach where manufacturing begins only after an actual customer order is received, common for customized, low-volume, high-value goods.", "source_pdf_page": 13}, {"id": "MIS-ASSIGN-W05-Q02", "week": 5, "question_num": 2, "question": "In a manufacturing information system, which document formally authorizes the start of production?", "option_a": "Goods receipt note", "option_b": "Production order", "option_c": "Sales quotation", "option_d": "Purchase requisition", "correct_answer": "B", "topic": "Manufacturing Execution & Work Orders", "solution": "A Production Order (or Work Order) is the formal document generated by the production planning system that authorizes the shop floor to produce a specified quantity of goods by a specified date.", "source_pdf_page": 13}, {"id": "MIS-ASSIGN-W05-Q03", "week": 5, "question_num": 3, "question": "Which of the following would be considered a tactical information requirement for manufacturing management?", "option_a": "Long-term product design decisions", "option_b": "Factory location planning", "option_c": "Quality control measures", "option_d": "Corporate acquisition strategy", "correct_answer": "C", "topic": "Managerial Information Hierarchy (Tactical)", "solution": "Tactical decisions deal with medium-term resource allocation, performance monitoring, and quality control metrics, whereas factory location and corporate acquisitions are strategic.", "source_pdf_page": 13}, {"id": "MIS-ASSIGN-W05-Q04", "week": 5, "question_num": 4, "question": "A production manager wants to identify the optimal product mix under limited machine capacity. This decision falls under:", "option_a": "Strategic information", "option_b": "Tactical information", "option_c": "Operational information", "option_d": "Transaction processing", "correct_answer": "B", "topic": "Tactical Capacity Optimization", "solution": "Determining product mix and allocating constrained machine capacity across quarters is a classic tactical management decision requiring optimization models and aggregate planning data.", "source_pdf_page": 14}, {"id": "MIS-ASSIGN-W05-Q05", "week": 5, "question_num": 5, "question": "Which statement best explains the difference between independent and dependent demand?", "option_a": "Independent demand is derived from BOM requirements.", "option_b": "Dependent demand originates directly from customer demand.", "option_c": "Independent demand is determined by market demand, while dependent demand is derived from it.", "option_d": "Both are determined by suppliers.", "correct_answer": "C", "topic": "Independent vs. Dependent Demand in MRP", "solution": "Independent demand refers to finished goods whose demand is determined directly by external market forces, whereas dependent demand refers to sub-assemblies and raw parts derived directly from the Bill of Materials.", "source_pdf_page": 14}, {"id": "MIS-ASSIGN-W05-Q06", "week": 5, "question_num": 6, "question": "The Bill of Materials (BOM) primarily serves as:", "option_a": "A financial statement", "option_b": "A hierarchical listing of components needed to manufacture a product", "option_c": "A quality inspection report", "option_d": "A vendor evaluation document", "correct_answer": "B", "topic": "Bill of Materials (BOM) Structure", "solution": "The Bill of Materials (BOM) is a master recipe and hierarchical tree listing every subassembly, component, and raw material required to manufacture one unit of a finished product.", "source_pdf_page": 14}, {"id": "MIS-ASSIGN-W05-Q07", "week": 5, "question_num": 7, "question": "Which MRP input specifies when finished products must be completed?", "option_a": "Inventory records", "option_b": "Capacity plan", "option_c": "Master Production Schedule", "option_d": "Routing sheet", "correct_answer": "C", "topic": "Master Production Schedule (MPS)", "solution": "The Master Production Schedule (MPS) states what finished products are to be manufactured, in what quantities, and by what exact dates.", "source_pdf_page": 14}, {"id": "MIS-ASSIGN-W05-Q08", "week": 5, "question_num": 8, "question": "Capacity Requirement Planning (CRP) is mainly concerned with:", "option_a": "Forecasting demand", "option_b": "Determining whether sufficient production capacity exists", "option_c": "Designing new products", "option_d": "Monitoring customer satisfaction", "correct_answer": "B", "topic": "Capacity Requirement Planning (CRP)", "solution": "Capacity Requirement Planning (CRP) checks the planned orders from MRP against the machine work centers and labor hours available to verify feasibility.", "source_pdf_page": 15}, {"id": "MIS-ASSIGN-W05-Q09", "week": 5, "question_num": 9, "question": "Which technology allows engineers to visualize and test products before physical prototypes are built?", "option_a": "ERP", "option_b": "SPC", "option_c": "CAD", "option_d": "CRM", "correct_answer": "C", "topic": "Computer-Aided Design (CAD)", "solution": "Computer-Aided Design (CAD) automates the creation, revision, and 3D simulation of designs using sophisticated graphics software prior to committing to tooling and fabrication.", "source_pdf_page": 15}, {"id": "MIS-ASSIGN-W05-Q10", "week": 5, "question_num": 10, "question": "A major advantage of additive manufacturing over traditional manufacturing is:", "option_a": "Elimination of all design costs", "option_b": "Rapid prototyping with minimal tooling", "option_c": "Reduced need for digital designs", "option_d": "Lower computing requirements", "correct_answer": "B", "topic": "Additive Manufacturing (3D Printing)", "solution": "Additive manufacturing (3D printing) builds parts layer-by-layer directly from digital 3D models, enabling rapid prototyping and customized geometry with minimal specialized tooling.", "source_pdf_page": 15}, {"id": "MIS-ASSIGN-W06-Q01", "week": 6, "question_num": 1, "question": "The primary objective of a Marketing Information System (MKIS) is to:", "option_a": "Automate payroll processing", "option_b": "Support marketing decision-making through relevant information", "option_c": "Manage production schedules", "option_d": "Monitor employee attendance", "correct_answer": "B", "topic": "Marketing Information Systems (MKIS)", "solution": "A Marketing Information System (MKIS) gathers, analyzes, and distributes timely, accurate information to marketing managers to improve pricing, promotion, product development, and distribution decisions.", "source_pdf_page": 16}, {"id": "MIS-ASSIGN-W06-Q02", "week": 6, "question_num": 2, "question": "In the marketing research process, data collection should occur:", "option_a": "Before defining the problem", "option_b": "After implementing recommendations", "option_c": "After defining objectives and research questions", "option_d": "Before identifying information needs", "correct_answer": "C", "topic": "Marketing Research Process", "solution": "Methodologically, data collection can only proceed effectively after the business problem, research scope, specific objectives, and hypothesis questions have been formulated.", "source_pdf_page": 16}, {"id": "MIS-ASSIGN-W06-Q03", "week": 6, "question_num": 3, "question": "Which subsystem continuously scans the external environment for information on competitors and market trends?", "option_a": "Internal Reports Subsystem", "option_b": "Marketing Intelligence Subsystem", "option_c": "Pricing Subsystem", "option_d": "Sales Forecasting Subsystem", "correct_answer": "B", "topic": "Marketing Intelligence Subsystems", "solution": "The Marketing Intelligence subsystem is the set of procedures and sources that managers use to obtain everyday information about pertinent developments in the external marketing environment and competitors.", "source_pdf_page": 16}, {"id": "MIS-ASSIGN-W06-Q04", "week": 6, "question_num": 4, "question": "A company uses customer demographics, purchasing history, and psychographic data to identify target segments. This information comes primarily from:", "option_a": "Customer databases", "option_b": "Payroll records", "option_c": "SPC systems", "option_d": "Capacity planning systems", "correct_answer": "A", "topic": "Customer Profiling & Databases", "solution": "Consolidated customer databases (part of CRM and marketing systems) store transaction records, demographic profiles, and interaction channels used for market segmentation.", "source_pdf_page": 17}, {"id": "MIS-ASSIGN-W06-Q05", "week": 6, "question_num": 5, "question": "Which forecasting method relies most heavily on historical sales patterns?", "option_a": "Delphi technique", "option_b": "Scenario planning", "option_c": "Time-series analysis", "option_d": "Expert panels", "correct_answer": "C", "topic": "Sales Forecasting Methods", "solution": "Time-series analysis relies on statistical models that analyze past chronological data points to isolate trends, seasonal cycles, and recurring patterns to project future sales.", "source_pdf_page": 17}, {"id": "MIS-ASSIGN-W06-Q06", "week": 6, "question_num": 6, "question": "The greatest advantage of Sales Force Automation is:", "option_a": "Eliminating customer interactions", "option_b": "Instant access to organizational information during selling activities", "option_c": "Replacing marketing research", "option_d": "Reducing product quality costs", "correct_answer": "B", "topic": "Sales Force Automation (SFA)", "solution": "Sales Force Automation equips field sales reps with mobile devices that give real-time access to corporate inventories, pricing discounts, customer credit terms, and order submission tools.", "source_pdf_page": 17}, {"id": "MIS-ASSIGN-W06-Q07", "week": 6, "question_num": 7, "question": "Before a sales order is confirmed, organizations commonly perform:", "option_a": "Employee screening", "option_b": "Credit verification", "option_c": "Vendor rating", "option_d": "Capacity auditing", "correct_answer": "B", "topic": "Order Management & Credit Check", "solution": "In order-to-cash workflows, the system automatically checks the customer's credit limit and payment history before releasing a sales order for warehouse picking.", "source_pdf_page": 17}, {"id": "MIS-ASSIGN-W06-Q08", "week": 6, "question_num": 8, "question": "Which activity immediately follows picking and packing in the sales distribution process?", "option_a": "Recruitment", "option_b": "Payroll approval", "option_c": "Transportation and shipment arrangement", "option_d": "Vendor evaluation", "correct_answer": "C", "topic": "Order Fulfillment Process", "solution": "Once items are picked from warehouse shelves and packed into shipping cartons, logistics schedules carrier transportation, issues the bill of lading, and initiates shipping.", "source_pdf_page": 17}, {"id": "MIS-ASSIGN-W06-Q09", "week": 6, "question_num": 9, "question": "The primary purpose of Accounts Receivable is to:", "option_a": "Manage supplier payments", "option_b": "Track money owed by customers", "option_c": "Maintain payroll records", "option_d": "Monitor inventory", "correct_answer": "B", "topic": "Financial Information Systems (AR)", "solution": "Accounts Receivable (AR) records and manages debts owed to the enterprise by customers who have purchased goods or services on credit.", "source_pdf_page": 18}, {"id": "MIS-ASSIGN-W06-Q10", "week": 6, "question_num": 10, "question": "A customer returns damaged goods after invoicing. Which accounting document is most likely generated?", "option_a": "Debit note", "option_b": "Purchase requisition", "option_c": "Inspection certificate", "option_d": "Credit note", "correct_answer": "D", "topic": "Billing & Accounting Adjustments", "solution": "A Credit Note (or Credit Memo) is issued by a seller to a buyer to reduce the amount the customer owes under an invoice, commonly due to damaged, returned, or overbilled merchandise.", "source_pdf_page": 18}, {"id": "MIS-ASSIGN-W07-Q01", "week": 7, "question_num": 1, "question": "Business strategy is a function of:", "option_a": "Competition, Positioning, and Capabilities", "option_b": "Hardware, Software, and Data", "option_c": "Revenue, Cost, and Profit", "option_d": "Customers, Vendors, and Employees", "correct_answer": "A", "topic": "Strategic Alignment Framework", "solution": "In strategic management, an enterprise's business strategy is dictated by competitive industry forces, market positioning, and internal organizational capabilities.", "source_pdf_page": 19}, {"id": "MIS-ASSIGN-W07-Q02", "week": 7, "question_num": 2, "question": "Which model is used for organizational design?", "option_a": "SWOT Matrix", "option_b": "Business Diamond", "option_c": "BCG Matrix", "option_d": "Ansoff Matrix", "correct_answer": "B", "topic": "Leavitt's Business Diamond", "solution": "Leavitt's Business Diamond model is a foundational framework for organizational design and change management, demonstrating that altering one component requires rebalancing the others.", "source_pdf_page": 19}, {"id": "MIS-ASSIGN-W07-Q03", "week": 7, "question_num": 3, "question": "The Business Diamond consists of:", "option_a": "Finance, Marketing, HR, Operations", "option_b": "Hardware, Software, Network, Data", "option_c": "People, Structure, Tasks, Information Control", "option_d": "Cost, Quality, Time, Flexibility", "correct_answer": "C", "topic": "Business Diamond Dimensions", "solution": "The four interrelated corners of Leavitt's Diamond are Tasks (processes), People (skills and culture), Structure (hierarchy and organization), and Information & Technology (control mechanisms).", "source_pdf_page": 19}, {"id": "MIS-ASSIGN-W07-Q04", "week": 7, "question_num": 4, "question": "Which is NOT an IS infrastructure component?", "option_a": "Hardware", "option_b": "Software", "option_c": "Network", "option_d": "Advertising", "correct_answer": "D", "topic": "IT Infrastructure Components", "solution": "IT infrastructure is composed of computer hardware, software, data management technology, and networking/telecommunications facilities. Advertising is a marketing communication activity, not an IS infrastructure element.", "source_pdf_page": 19}, {"id": "MIS-ASSIGN-W07-Q05", "week": 7, "question_num": 5, "question": "Changing one corner of the IS Strategy Triangle requires:", "option_a": "No action", "option_b": "Evaluating the other two corners", "option_c": "Hiring more staff", "option_d": "Increasing profits", "correct_answer": "B", "topic": "Information Systems Strategy Triangle", "solution": "The IS Strategy Triangle dictates that Business Strategy, Organizational Strategy, and Information Strategy must remain in balance. Changing any one corner requires evaluating and adjusting the other two.", "source_pdf_page": 20}, {"id": "MIS-ASSIGN-W07-Q06", "week": 7, "question_num": 6, "question": "Strategic Systems Analysis examines:", "option_a": "Industry structure and competitive forces", "option_b": "Employee attendance only", "option_c": "Payroll systems only", "option_d": "Accounting records only", "correct_answer": "A", "topic": "Strategic Systems Analysis", "solution": "Strategic Systems Analysis systematically evaluates competitive industry structure, Porter's Five Forces, corporate value chains, and core competencies to identify high-ROI strategic IT opportunities.", "source_pdf_page": 20}, {"id": "MIS-ASSIGN-W07-Q07", "week": 7, "question_num": 7, "question": "Balanced Scorecard (BSC) focuses on:", "option_a": "Only financial performance", "option_b": "Four dimensions of performance", "option_c": "Employee salaries", "option_d": "Product prices only", "correct_answer": "B", "topic": "Balanced Scorecard Framework", "solution": "Developed by Kaplan and Norton, the Balanced Scorecard supplements traditional financial measures with three operational perspectives: Customer, Internal Business Processes, and Learning & Growth.", "source_pdf_page": 20}, {"id": "MIS-ASSIGN-W07-Q08", "week": 7, "question_num": 8, "question": "Which is NOT one of the four BSC dimensions?", "option_a": "Customer", "option_b": "Financial", "option_c": "Business Process", "option_d": "Manufacturing Capacity", "correct_answer": "D", "topic": "Four Balanced Scorecard Perspectives", "solution": "The official four dimensions are Financial, Customer, Internal Business Processes, and Learning/Growth. Manufacturing Capacity is a specific operational sub-metric, not a distinct BSC perspective.", "source_pdf_page": 20}, {"id": "MIS-ASSIGN-W07-Q09", "week": 7, "question_num": 9, "question": "KPIs in a BSC are:", "option_a": "Key Performance Indicators", "option_b": "Knowledge Processing Instructions", "option_c": "Key Product Integrators", "option_d": "Knowledge Performance Interfaces", "correct_answer": "A", "topic": "Key Performance Indicators (KPIs)", "solution": "KPIs stands for Key Performance Indicators—quantifiable metrics used by managers to evaluate an organization's progress toward achieving its strategic goals.", "source_pdf_page": 20}, {"id": "MIS-ASSIGN-W07-Q10", "week": 7, "question_num": 10, "question": "BSC helps managers focus on:", "option_a": "Strategic vision", "option_b": "Office administration only", "option_c": "Accounting entries only", "option_d": "Legal compliance only", "correct_answer": "A", "topic": "Balanced Scorecard Strategic Alignment", "solution": "The fundamental purpose of the Balanced Scorecard is to translate an organization's overarching mission and strategic vision into concrete, actionable performance objectives.", "source_pdf_page": 21}, {"id": "MIS-ASSIGN-W08-Q01", "week": 8, "question_num": 1, "question": "E-commerce refers to:", "option_a": "Physical transactions only", "option_b": "Digitally enabled commercial transactions involving exchange of value", "option_c": "Internal organizational communication", "option_d": "Manufacturing automation", "correct_answer": "B", "topic": "E-Commerce Definition", "solution": "E-commerce is defined formally as digitally enabled commercial transactions between and among organizations and individuals, involving the exchange of economic value across institutional boundaries.", "source_pdf_page": 22}, {"id": "MIS-ASSIGN-W08-Q02", "week": 8, "question_num": 2, "question": "Which feature of e-commerce allows access to markets anytime and anywhere?", "option_a": "Richness", "option_b": "Interactivity", "option_c": "Ubiquity", "option_d": "Customization", "correct_answer": "C", "topic": "Ubiquity Dimension of E-Commerce", "solution": "Ubiquity means internet/web technology is available everywhere: at work, at home, and elsewhere via mobile devices anytime, creating a 'marketspace' liberated from physical location.", "source_pdf_page": 22}, {"id": "MIS-ASSIGN-W08-Q03", "week": 8, "question_num": 3, "question": "The ability of e-commerce to reach across national boundaries is known as:", "option_a": "Information density", "option_b": "Global reach", "option_c": "Personalization", "option_d": "Interactivity", "correct_answer": "B", "topic": "Global Reach in Digital Markets", "solution": "Global reach refers to the technology's capability to traverse national boundaries seamlessly, making commerce possible across cultural and national geographic perimeters.", "source_pdf_page": 22}, {"id": "MIS-ASSIGN-W08-Q04", "week": 8, "question_num": 4, "question": "Information density in e-commerce means information is:", "option_a": "Limited and costly", "option_b": "Plentiful, cheap, and accurate", "option_c": "Only available to firms", "option_d": "Difficult to access", "correct_answer": "B", "topic": "Information Density", "solution": "Information density is the total amount and quality of information available to all market participants. E-commerce dramatically lowers storage, communication, and processing costs while raising timeliness.", "source_pdf_page": 22}, {"id": "MIS-ASSIGN-W08-Q05", "week": 8, "question_num": 5, "question": "Adjusting marketing messages based on a customer's clickstream behavior is called:", "option_a": "Customization", "option_b": "Segmentation", "option_c": "Personalization", "option_d": "Automation", "correct_answer": "C", "topic": "Personalization in E-Commerce", "solution": "Personalization allows merchants to target marketing messages to specific individuals by adjusting the message to a person's name, interests, clickstream history, and past purchases.", "source_pdf_page": 23}, {"id": "MIS-ASSIGN-W08-Q06", "week": 8, "question_num": 6, "question": "Changing a delivered product based on user preferences is known as:", "option_a": "Personalization", "option_b": "Customization", "option_c": "Standardization", "option_d": "Diversification", "correct_answer": "B", "topic": "Customization in E-Commerce", "solution": "Customization involves changing the delivered product or service based on a user's explicit preferences or prior behavior.", "source_pdf_page": 23}, {"id": "MIS-ASSIGN-W08-Q07", "week": 8, "question_num": 7, "question": "Amazon is an example of which type of e-commerce?", "option_a": "B2B", "option_b": "C2C", "option_c": "B2C", "option_d": "G2C", "correct_answer": "C", "topic": "Business-to-Consumer (B2C) E-Commerce", "solution": "Business-to-Consumer (B2C) e-commerce involves retailing products and services to individual consumer shoppers, of which Amazon is the global archetype.", "source_pdf_page": 23}, {"id": "MIS-ASSIGN-W08-Q08", "week": 8, "question_num": 8, "question": "IndiaMART is primarily an example of:", "option_a": "B2B e-commerce", "option_b": "C2C e-commerce", "option_c": "Social commerce", "option_d": "Mobile commerce", "correct_answer": "A", "topic": "Business-to-Business (B2B) Marketplaces", "solution": "IndiaMART is an online B2B marketplace platform that connects wholesale buyers with manufacturers, distributors, and suppliers.", "source_pdf_page": 23}, {"id": "MIS-ASSIGN-W08-Q09", "week": 8, "question_num": 9, "question": "Which of the following is a major challenge in e-commerce?", "option_a": "Global reach", "option_b": "Personalization", "option_c": "Trust issues", "option_d": "Richness", "correct_answer": "C", "topic": "E-Commerce Security & Trust Challenges", "solution": "Trust issues (transactional fraud, identity theft, credit card privacy, and vendor legitimacy) remain among the foremost behavioral barriers in online commerce.", "source_pdf_page": 23}, {"id": "MIS-ASSIGN-W08-Q10", "week": 8, "question_num": 10, "question": "Which key element of a business model answers 'How to earn money?'", "option_a": "Market strategy", "option_b": "Competitive advantage", "option_c": "Revenue model", "option_d": "Market opportunity", "correct_answer": "C", "topic": "E-Commerce Revenue Models", "solution": "An enterprise's revenue model describes explicitly how the firm will earn revenue, generate profits, and produce a superior return on invested capital.", "source_pdf_page": 24}, {"id": "MIS-ASSIGN-W09-Q01", "week": 9, "question_num": 1, "question": "Which of the following is not a benefit of cloud computing?", "option_a": "Usage-based pricing", "option_b": "Resource Pooling", "option_c": "Increased Set-up Time", "option_d": "Measured Use", "correct_answer": "C", "topic": "Cloud Computing Characteristics", "solution": "Cloud computing offers rapid elasticity and on-demand provisioning, which dramatically decreases (rather than increases) infrastructure setup time.", "source_pdf_page": 25}, {"id": "MIS-ASSIGN-W09-Q02", "week": 9, "question_num": 2, "question": "Salesforce.com's CRM software is an example of which cloud service model?", "option_a": "IaaS", "option_b": "PaaS", "option_c": "SaaS", "option_d": "DaaD", "correct_answer": "C", "topic": "Software as a Service (SaaS)", "solution": "Salesforce provides an end-user application accessible entirely over web browsers without requiring customers to manage operating systems or servers, making it a classic SaaS model.", "source_pdf_page": 25}, {"id": "MIS-ASSIGN-W09-Q03", "week": 9, "question_num": 3, "question": "FinTech Solutions Inc. is developing a new customer-facing analytics portal. To accelerate their release timeline, they decide to use a cloud-based environment where the vendor hosts the runtime, libraries, testing tools, and plugins. Which cloud service model is FinTech Solutions utilizing for this analytics portal, and who is fundamentally responsible for ensuring the availability, bandwidth, and security at the hypervisor layer?", "option_a": "PaaS; The Cloud Vendor is responsible for the underlying infrastructure capacity, virtual networking, and hypervisor security.", "option_b": "PaaS; The Client manages the physical hardware, while the Cloud Vendor manages capacity.", "option_c": "SaaS; The Cloud Vendor manages only the application logic, while the Client manages all security and networking.", "option_d": "SaaS; The Cloud Vendor and Client share the hypervisor layer responsibility.", "correct_answer": "A", "topic": "Platform as a Service (PaaS) Shared Responsibility", "solution": "PaaS supplies the execution environment and development libraries. In PaaS, the cloud provider manages infrastructure, virtual networking, hypervisors, and physical hardware, while the customer manages application code and data.", "source_pdf_page": 26}, {"id": "MIS-ASSIGN-W09-Q04", "week": 9, "question_num": 4, "question": "GlobalHealth Inc. uses its own dedicated, single-tenant servers to securely store highly sensitive patient data. To handle unpredictable spikes in public appointment bookings, the company temporarily offloads web traffic to a globally shared network. What cloud deployment model does GlobalHealth Inc. utilize?", "option_a": "Public cloud", "option_b": "Community cloud", "option_c": "Private cloud", "option_d": "Hybrid cloud", "correct_answer": "D", "topic": "Hybrid Cloud Architecture", "solution": "A hybrid cloud deployment combines internal on-premises private infrastructure (for sensitive medical records) with public cloud instances (for handling variable web traffic spikes and appointment portals).", "source_pdf_page": 26}, {"id": "MIS-ASSIGN-W09-Q05", "week": 9, "question_num": 5, "question": "Tools or mechanisms that can change their own state and/or the state of other devices and machines are called _______________.", "option_a": "Sensors", "option_b": "IoT", "option_c": "Actuators", "option_d": "Proximity Sensor", "correct_answer": "C", "topic": "IoT Actuators", "solution": "While sensors detect and measure physical phenomena, actuators are mechanisms that convert electronic control signals into physical actions (moving, heating, opening valves, or switching relays).", "source_pdf_page": 26}, {"id": "MIS-ASSIGN-W09-Q06", "week": 9, "question_num": 6, "question": "Which of the following best describes the core approach of Privacy by Design?", "option_a": "Applying privacy settings as an optional add-on near the end of a project's development", "option_b": "Proactively considering privacy objectives from the start and throughout the design and delivery", "option_c": "Reacting to data breaches by applying immediate remedial software patches", "option_d": "Allowing users to manually select every privacy feature from a complex menu", "correct_answer": "B", "topic": "Privacy by Design Principles", "solution": "Privacy by Design dictates that privacy and data protection are embedded proactively into the technological architecture and business processes from the very inception of system development.", "source_pdf_page": 27}, {"id": "MIS-ASSIGN-W09-Q07", "week": 9, "question_num": 7, "question": "What is the primary function of a sensor in an IoT system?", "option_a": "To convert an electrical signal into a physical action", "option_b": "To capture environmental data and convert it into an electrical signal", "option_c": "To store massive amounts of data in the cloud", "option_d": "To provide power to the IoT device", "correct_answer": "B", "topic": "IoT Sensors", "solution": "Sensors detect physical inputs (temperature, vibration, pressure, light) from the physical environment and convert them into measurable electronic signals.", "source_pdf_page": 27}, {"id": "MIS-ASSIGN-W09-Q08", "week": 9, "question_num": 8, "question": "Which of the following statements accurately describes an Outsourced Private Cloud?", "option_a": "It is implemented solely within the customer's own premises.", "option_b": "The server side is managed by a hosting company.", "option_c": "It is designed and shared to serve the general public.", "option_d": "The infrastructure is always owned and operated by the customer's internal IT team.", "correct_answer": "B", "topic": "Outsourced Private Cloud", "solution": "In an outsourced private cloud, the infrastructure is dedicated exclusively to one single organization but is physically housed, managed, and maintained offsite by a third-party hosting company.", "source_pdf_page": 27}, {"id": "MIS-ASSIGN-W09-Q09", "week": 9, "question_num": 9, "question": "A retail e-commerce giant is consolidating multiple distinct data streams from their 2026 Black Friday campaign to predict consumer churn. They aggregate Stream A (binary biometric data), Stream B (unstructured social text and emojis), and Stream C (structured SQL logs). They discover 15% missing timestamps and 20% spam bots. Which of the following best diagnoses the system's challenges by correctly applying the concepts of Variety and Veracity?", "option_a": "The integration of wearable devices, social media, and transactional logs represents a Variety challenge, while timestamp gaps and spam bots represent a Veracity challenge.", "option_b": "The data format differences between binary files, text, and JSON represent a Veracity challenge, while missing timestamps in the wearable data represent a Variety challenge.", "option_c": "The integration of different platforms (sensors, social media, SQL) represents a Veracity challenge, while the presence of bot spam and missing intervals both strictly represent Variety issues.", "option_d": "Both the format differences (Stream A, B, C) and the missing intervals are examples of Variety, whereas the presence of bot spam is an example of Veracity.", "correct_answer": "A", "topic": "Big Data Dimensions: Variety vs. Veracity", "solution": "Variety encompasses different formats (binary sensor streams, text reviews, structured relational tables). Veracity refers to data trustworthiness, cleanliness, and fidelity (missing timestamps and fraudulent bot spam).", "source_pdf_page": 28}, {"id": "MIS-ASSIGN-W09-Q10", "week": 9, "question_num": 10, "question": "Which among the following is a cloud service provider?", "option_a": "Netflix", "option_b": "JioHotstar", "option_c": "Reliance Digital", "option_d": "DigitalOcean", "correct_answer": "D", "topic": "Cloud Infrastructure Providers", "solution": "DigitalOcean is a prominent cloud infrastructure provider offering on-demand virtual compute droplets, storage, and networking.", "source_pdf_page": 28}, {"id": "MIS-ASSIGN-W10-Q01", "week": 10, "question_num": 1, "question": "____________ is the collective and individual experience of applying knowledge to the solution of problem; knowing when, where, and how to apply that knowledge.", "option_a": "Cognition", "option_b": "Wisdom", "option_c": "Tacit", "option_d": "Culture", "correct_answer": "B", "topic": "Knowledge Hierarchy (Wisdom)", "solution": "Wisdom is defined in MIS as the collective and individual experience of applying knowledge to solve problems, encompassing practical judgment of when, where, and how to apply insights.", "source_pdf_page": 29}, {"id": "MIS-ASSIGN-W10-Q02", "week": 10, "question_num": 2, "question": "A retail manager uses an IT system that instantly pulls historical sales data and expert staff insights to determine the best price for a new product line. Which system is being used to practically apply organizational knowledge and add ROI to this decision?", "option_a": "Transaction Processing System", "option_b": "Office Automation System", "option_c": "Supply Chain Management System", "option_d": "Decision Support System (DSS)", "correct_answer": "D", "topic": "Decision Support Systems (DSS)", "solution": "A Decision Support System (DSS) combines analytical models, historical transaction data, and manager judgment to support semi-structured decision scenarios such as pricing optimization.", "source_pdf_page": 29}, {"id": "MIS-ASSIGN-W10-Q03", "week": 10, "question_num": 3, "question": "Which of the following best describes a primary difference between a Neural Network and a Genetic Algorithm in organizational knowledge management?", "option_a": "Genetic Algorithms are used to discover hidden patterns in data, whereas Neural Networks are used to evaluate alternative solutions.", "option_b": "Neural Networks are used to discover patterns in data, whereas Genetic Algorithms are used to evaluate and optimize alternative solutions.", "option_c": "Neural Networks rely on Darwinian evolution, while Genetic Algorithms rely on human nervous system models.", "option_d": "Both act identically but process data sequentially rather than in parallel.", "correct_answer": "B", "topic": "AI Techniques in Knowledge Systems", "solution": "Neural Networks excel at pattern recognition and classification from vast empirical datasets, whereas Genetic Algorithms excel at optimization problems by evaluating alternative candidate solutions through simulated evolutionary processes.", "source_pdf_page": 29}, {"id": "MIS-ASSIGN-W10-Q04", "week": 10, "question_num": 4, "question": "Which scenario best illustrates a semi-structured decision type?", "option_a": "Adjusting the monthly production output purely according to historical seasonal sales data.", "option_b": "Formulating an annual corporate budget by rigidly enforcing standard inflation-adjusted formulas.", "option_c": "Determining the most cost-effective customized delivery route for a new, irregularly shaped geographical zone.", "option_d": "Approving a standard expense report that strictly complies with the published company travel policy.", "correct_answer": "C", "topic": "Decision Characteristics: Semi-Structured Decisions", "solution": "Determining an optimal routing configuration across an irregular geography contains both structured mathematical constraints (mileage, transit speeds) and unstructured human judgment (road hazards, driver familiarity), making it semi-structured.", "source_pdf_page": 30}, {"id": "MIS-ASSIGN-W10-Q05", "week": 10, "question_num": 5, "question": "Which of the following is not a phase in a decision-making process?", "option_a": "Intelligence", "option_b": "Design", "option_c": "Choice", "option_d": "Scope", "correct_answer": "D", "topic": "Simon's Four Stages of Decision-Making", "solution": "Herbert Simon's classic four stages of decision-making are Intelligence (problem identification), Design (solution development), Choice (selecting among alternatives), and Implementation. 'Scope' is not one of Simon's stages.", "source_pdf_page": 30}, {"id": "MIS-ASSIGN-W10-Q06", "week": 10, "question_num": 6, "question": "According to the principles of Management Information Systems, which type of decisions do Executive Support Systems (ESS) primarily address?", "option_a": "Routine and highly structured operational decisions", "option_b": "Non-routine decisions requiring judgment, evaluation, and insight", "option_c": "Strictly day-to-day tactical management decisions", "option_d": "Pre-programmed, repetitive transaction processing", "correct_answer": "B", "topic": "Executive Support Systems (ESS)", "solution": "Executive Support Systems (ESS) serve senior executive management by addressing non-routine decisions requiring strategic judgment, evaluation, and holistic organizational insight.", "source_pdf_page": 30}, {"id": "MIS-ASSIGN-W10-Q07", "week": 10, "question_num": 7, "question": "Which of the following statements best defines object-based knowledge representation for expert systems?", "option_a": "Knowledge is represented as simple true/false statements without any attached data.", "option_b": "Knowledge is represented as a network of objects, where each object contains both data and the methods that act on that data.", "option_c": "Knowledge is strictly stored as a sequential list of procedural algorithms.", "option_d": "Knowledge is represented purely through unstructured text files.", "correct_answer": "B", "topic": "Knowledge Representation Schemes", "solution": "In object-oriented knowledge representation, concepts and physical entities are stored as discrete objects that encapsulate both descriptive attributes (data) and executable behaviors (methods).", "source_pdf_page": 30}, {"id": "MIS-ASSIGN-W10-Q08", "week": 10, "question_num": 8, "question": "A local hospital is using an AI expert system to help emergency doctors diagnose patients with severe respiratory distress. When a patient arrives, the doctor first inputs specific symptoms (e.g., sudden fever, dry cough, and shortness of breath) into the system. The inference engine immediately analyzes these available facts, checks them against thousands of nested medical rules, and progressively infers potential conditions and treatment options until it derives a set of probable diagnoses. Based on how the inference engine processes the data, which reasoning strategy is the system using?", "option_a": "Backward Chaining", "option_b": "Goal-Driven Analysis", "option_c": "Breadth-First Deductive Reasoning", "option_d": "Forward Chaining", "correct_answer": "D", "topic": "Inference Engines: Forward vs. Backward Chaining", "solution": "Forward chaining is a data-driven reasoning strategy: it begins with gathered empirical facts and symptoms, fires rules whose conditions match those facts, and proceeds forward to infer a conclusion (diagnosis).", "source_pdf_page": 31}, {"id": "MIS-ASSIGN-W10-Q09", "week": 10, "question_num": 9, "question": "What do the letters in the acronym MOODLE stand for?", "option_a": "Modern Object-Oriented Dynamic Learning Environment", "option_b": "Modular Object-Oriented Dynamic Learning Environment", "option_c": "Managed Open Online Distance Learning Experience", "option_d": "Modular Open Online Digital Learning Engine", "correct_answer": "B", "topic": "Learning Management Systems (MOODLE)", "solution": "MOODLE is the global open-source learning management standard and stands for Modular Object-Oriented Dynamic Learning Environment.", "source_pdf_page": 31}, {"id": "MIS-ASSIGN-W10-Q10", "week": 10, "question_num": 10, "question": "Which type of managerial decision is routine, repetitive, and follows a predefined set of rules or standard operating procedures?", "option_a": "Semi-structured", "option_b": "Unstructured", "option_c": "Structured", "option_d": "Analytical", "correct_answer": "C", "topic": "Structured Decision Making", "solution": "Structured decisions are repetitive and routine, involving a definite, standardized procedure for handling them so that they do not have to be treated as brand new each time (e.g. inventory restocking or overtime approval).", "source_pdf_page": 31}, {"id": "MIS-ASSIGN-W11-Q01", "week": 11, "question_num": 1, "question": "Which of the following statements regarding the Right to Privacy is false?", "option_a": "It involves the right to be left alone and free from unreasonable personal intrusions.", "option_b": "It is an absolute right that takes total precedence over the needs of society.", "option_c": "It must be balanced against the broader needs and interests of society.", "option_d": "The public's right to know is often considered superior to an individual's right to privacy.", "correct_answer": "B", "topic": "Ethical and Social Dimensions of Privacy", "solution": "In legal and ethical philosophy, privacy is not an absolute right; it must be balanced against public safety, law enforcement mandates, national security, and societal welfare.", "source_pdf_page": 32}, {"id": "MIS-ASSIGN-W11-Q02", "week": 11, "question_num": 2, "question": "What are computer cookies, as described in web technology?", "option_a": "Small text files deposited on a computer's hard drive to identify and track visits", "option_b": "Hidden software applications that delete a user's browsing history", "option_c": "Programs used by hackers to steal personal passwords", "option_d": "Temporary internet cables that connect to web servers", "correct_answer": "A", "topic": "Web Privacy & Tracking Technologies", "solution": "Cookies are small text strings deposited on a client device's browser by web servers to record site preferences, remember shopping carts, and track user navigation.", "source_pdf_page": 32}, {"id": "MIS-ASSIGN-W11-Q03", "week": 11, "question_num": 3, "question": "Zenith Corp implements a new Information System (IS) that tracks keystrokes, active window times, and web browsing habits. During the rollout, management announces that the system will generate random, automated performance audits, but the exact tracking schedule is kept strictly confidential. Initially, a few remote workers attempt to browse non-work-related websites during business hours. However, realising the logging software could be recording their activity at any given minute, employees began limiting their computer use strictly to corporate tasks. Which of the following best explains why Zenith Corp employees consistently conform to company policies despite the lack of a visible or constant human supervisor?", "option_a": "Hawthorne Effect", "option_b": "The Panopticon Effect", "option_c": "Groupthink", "option_d": "Cognitive Dissonance", "correct_answer": "B", "topic": "Surveillance & The Panopticon Effect", "solution": "The Panopticon effect (originally conceptualized by Jeremy Bentham and expanded by Michel Foucault) explains how subjects alter and discipline their behavior because they know they might be monitored at any moment, even if monitoring is not continuous.", "source_pdf_page": 32}, {"id": "MIS-ASSIGN-W11-Q04", "week": 11, "question_num": 4, "question": "Which of the following best describes the primary objective and function of a Man-in-the-Middle attack?", "option_a": "It overloads a target server's resources to cause a sudden disruption in legitimate user access.", "option_b": "It secretly intercepts, reads, and potentially alters communications between a sender and a recipient without their knowledge.", "option_c": "It tricks users into downloading and installing malicious software disguised as legitimate applications.", "option_d": "It guesses passwords by systematically trying thousands of combinations until the correct one is found.", "correct_answer": "B", "topic": "Cybersecurity Threats: MITM Attacks", "solution": "In a Man-in-the-Middle (MITM) attack, the perpetrator secretly intercepts and relays communications between two parties who believe they are directly communicating with each other.", "source_pdf_page": 33}, {"id": "MIS-ASSIGN-W11-Q05", "week": 11, "question_num": 5, "question": "Which of the following cyber threats uses manipulative communication—such as bogus emails or messages—as its primary delivery method to steal an identity?", "option_a": "Pharming", "option_b": "DNS Cache Poisoning", "option_c": "Malware Encryption", "option_d": "Phishing", "correct_answer": "D", "topic": "Social Engineering & Phishing", "solution": "Phishing is a social engineering attack that involves sending deceptive emails or messages purporting to be from reputable companies to induce individuals to reveal passwords and credit card numbers.", "source_pdf_page": 33}, {"id": "MIS-ASSIGN-W11-Q06", "week": 11, "question_num": 6, "question": "Which of the following is the full form of VPN?", "option_a": "Visual Private Network", "option_b": "Virtual Private Node", "option_c": "Virtual Private Network", "option_d": "Visual Private Node", "correct_answer": "C", "topic": "Network Security (VPN)", "solution": "A Virtual Private Network (VPN) creates a secure, encrypted tunnel over public telecommunications networks (like the internet) to allow remote users secure access to corporate intranets.", "source_pdf_page": 33}, {"id": "MIS-ASSIGN-W11-Q07", "week": 11, "question_num": 7, "question": "A major server outage brings down the primary database for GlobalTech Solutions, instantly preventing their customer service team from accessing client records. While the IT department works on restoring the servers from the latest backup, the management team activates a backup procedure allowing agents to manually process urgent client requests using printed logs and temporary phone lines. In this scenario, which plans were demonstrated by the IT department and the management team, respectively?", "option_a": "Both the IT team and management demonstrated the Disaster Recovery Plan (DRP)", "option_b": "Both the IT team and management demonstrated the Business Continuity Plan (BCP)", "option_c": "The IT team demonstrated the Business Continuity Plan (BCP), and management demonstrated the Disaster Recovery Plan (DRP)", "option_d": "The IT team demonstrated the Disaster Recovery Plan (DRP), and management demonstrated the Business Continuity Plan (BCP)", "correct_answer": "D", "topic": "Disaster Recovery vs. Business Continuity Planning", "solution": "Disaster Recovery Planning (DRP) focuses technical efforts on restoring computing facilities, networks, and databases. Business Continuity Planning (BCP) focuses on managerial operational workarounds to keep business functions alive during an outage.", "source_pdf_page": 34}, {"id": "MIS-ASSIGN-W11-Q08", "week": 11, "question_num": 8, "question": "Which of the following is a primary requirement for financial institutions under the Gramm-Leach-Bliley Act (GLBA) regarding customer data?", "option_a": "To publicly disclose all customer account balances in a quarterly directory.", "option_b": "To ensure the security and confidentiality of customer non-public personal information.", "option_c": "To share customer financial data with unaffiliated third parties by default.", "option_d": "To destroy all customer financial records after one year of inactivity.", "correct_answer": "B", "topic": "Regulatory Compliance (GLBA)", "solution": "The Gramm-Leach-Bliley Act (GLBA) mandates that financial institutions establish comprehensive security programs to ensure the confidentiality and integrity of non-public consumer financial records.", "source_pdf_page": 34}, {"id": "MIS-ASSIGN-W11-Q09", "week": 11, "question_num": 9, "question": "Which of the following is not considered a primary problem or objective addressed by computer forensics?", "option_a": "Recovering data from computers while preserving evidential integrity", "option_b": "Finding significant information in a large volume of electronic data", "option_c": "Altering recovered data to better suit a specific court argument", "option_d": "Presenting the information to a court of law", "correct_answer": "C", "topic": "Computer Forensics Integrity", "solution": "Computer forensics strictly requires preserving evidential chain-of-custody without tampering. Altering or fabricating data violates legal and forensic ethics.", "source_pdf_page": 34}, {"id": "MIS-ASSIGN-W11-Q10", "week": 11, "question_num": 10, "question": "Which of the following is one of the leading Unified Threat Management (UTM) vendors?", "option_a": "Fortinent", "option_b": "McAfee", "option_c": "Trend Micro", "option_d": "Symantec", "correct_answer": "A", "topic": "Unified Threat Management (UTM)", "solution": "Fortinet (noted as Fortinent in NPTEL question transcript) is a premier global vendor specializing in enterprise Unified Threat Management appliances and next-generation firewalls.", "source_pdf_page": 35}, {"id": "MIS-ASSIGN-W12-Q01", "week": 12, "question_num": 1, "question": "Which of the following is not a characteristic of a global organization?", "option_a": "Large-scale operations", "option_b": "A large number of middlemen", "option_c": "Multi-Language, Mono-Cultural", "option_d": "High risk", "correct_answer": "C", "topic": "Characteristics of Global Organizations", "solution": "Global organizations operate across diverse regional markets and are distinctly multi-cultural and multi-lingual. A 'mono-cultural' profile is antithetical to global enterprise reality.", "source_pdf_page": 36}, {"id": "MIS-ASSIGN-W12-Q02", "week": 12, "question_num": 2, "question": "What is the very first step a firm must take when developing an International Information Systems Architecture?", "option_a": "Designing new business procedures and reengineering", "option_b": "Understanding the global environment and business drivers", "option_c": "Developing the corporate global strategy", "option_d": "Selecting the appropriate technology platform", "correct_answer": "B", "topic": "International Information Systems Architecture", "solution": "The first step in building a global systems architecture is to understand the external global environment: competitive business drivers, regional regulatory hurdles, and communication constraints.", "source_pdf_page": 36}, {"id": "MIS-ASSIGN-W12-Q03", "week": 12, "question_num": 3, "question": "GlobalTech Inc. is a global electronics manufacturer. Originally, its US headquarters made all product and marketing decisions, giving overseas branches very little freedom. Recently, the company restructured so that its subsidiaries in Japan, Germany, and India operate as highly integrated yet independent units. These local branches now have the autonomy to design specific products and marketing campaigns tailored to their own cultures, while still sharing global operational efficiencies. Based on the transition described, which of the following best represents the shift in GlobalTech Inc.'s organizational strategy?", "option_a": "From a Domestic Exporter to a Franchiser", "option_b": "From a Transnational Corporation to a Multinational Corporation", "option_c": "From a Franchiser to a Domestic Exporter", "option_d": "From a Multinational Corporation to a Transnational Corporation", "correct_answer": "D", "topic": "Global Organizational Strategies", "solution": "Transnational firms optimize global operational scale while decentralizing and empowering regional business units to tailor products to local markets, representing the shift from a traditional multinational/centralized structure.", "source_pdf_page": 37}, {"id": "MIS-ASSIGN-W12-Q04", "week": 12, "question_num": 4, "question": "An international bank's fraud detection engine continuously co-develops algorithms through real-time data sharing between teams in New York, London, and Tokyo. Each global hub simultaneously builds local patches while immediately syncing operational updates across the entire corporate infrastructure to maintain uniform security. Which systems configuration does this corporate strategy illustrate?", "option_a": "Networked", "option_b": "Duplicated", "option_c": "Centralized", "option_d": "Decentralized", "correct_answer": "A", "topic": "Global Systems Configurations (Networked)", "solution": "In a networked systems configuration, software development, data storage, and operational processing are shared collaboratively across interconnected international nodes rather than controlled from a single hub.", "source_pdf_page": 37}, {"id": "MIS-ASSIGN-W12-Q05", "week": 12, "question_num": 5, "question": "Which of the following activities falls under the category of 'back office functions'?", "option_a": "Catering for railway passengers", "option_b": "Advisory services for external clients", "option_c": "Training and R&D", "option_d": "Procurement of raw materials for production", "correct_answer": "C", "topic": "Back Office vs. Front Office Operations", "solution": "Back office operations comprise internal administrative, HR, infrastructure, training, and research & development activities that do not directly interface with external consumer clients.", "source_pdf_page": 37}, {"id": "MIS-ASSIGN-W12-Q06", "week": 12, "question_num": 6, "question": "Match each concept (column A) with the correct description (column B): 1. Resource sharing, 2. Centralization of services, 3. Joint Venture, 4. Outsourcing.", "option_a": "1–D, 2–B, 3–A, 4–C", "option_b": "1–B, 2–A, 3–C, 4–D", "option_c": "1–D, 2–B, 3–C, 4–A", "option_d": "1–A, 2–B, 3–C, 4–D", "correct_answer": "C", "topic": "Global Sourcing & Service Delivery Models", "solution": "1-D: Resource sharing uses plant/personnel across countries. 2-B: Centralization relocates services to a single shared hub. 3-C: Joint Venture creates a separate entity. 4-A: Outsourcing shifts processes to third-party providers.", "source_pdf_page": 38}, {"id": "MIS-ASSIGN-W12-Q07", "week": 12, "question_num": 7, "question": "During which transition activity are project records, manuals, and reports stored and handed over to the support team?", "option_a": "Human resource transition", "option_b": "Project documentation transition", "option_c": "Infrastructure transition", "option_d": "Financial transition", "correct_answer": "B", "topic": "IT Project Transition Activities", "solution": "The project documentation transition stream governs the formal handover of technical runbooks, architecture diagrams, user manuals, and maintenance logs to the ongoing support organization.", "source_pdf_page": 38}, {"id": "MIS-ASSIGN-W12-Q08", "week": 12, "question_num": 8, "question": "Which of the following represents the correct categorization of a Continuous Improvement activity within an outsourced support framework?", "option_a": "Root Cause Analysis", "option_b": "Value Realization", "option_c": "Evaluate learning effectiveness", "option_d": "Deliver continuous End User Training", "correct_answer": "B", "topic": "Continuous Improvement & Value Realization", "solution": "In IT outsourcing governance, Value Realization is the disciplined continuous improvement practice of tracking and harvesting projected strategic and financial benefits beyond standard SLA compliance.", "source_pdf_page": 38}, {"id": "MIS-ASSIGN-W12-Q09", "week": 12, "question_num": 9, "question": "Breakthroughs in transportation and telecommunication costs belong to which era of globalization?", "option_a": "Globalization 1.0", "option_b": "Globalization 2.0", "option_c": "Globalization 3.0", "option_d": "None of these", "correct_answer": "B", "topic": "Friedman's Eras of Globalization", "solution": "In Thomas Friedman's framework, Globalization 2.0 (1800 to 2000) was driven by multinational companies and technological breakthroughs in transportation (steam engines, rail) and communications (telegraph, telephone).", "source_pdf_page": 39}, {"id": "MIS-ASSIGN-W12-Q10", "week": 12, "question_num": 10, "question": "In the context of Thomas Friedman's 'Flat World' theory, how does 'In-forming' primarily benefit global corporations and individuals?", "option_a": "By restricting public access to corporate data to maintain a competitive advantage.", "option_b": "By replacing traditional human resources entirely with artificial intelligence.", "option_c": "By automating the physical assembly and manufacturing of products in overseas factories.", "option_d": "By providing everyone with the tools to build a personal information supply chain, democratising access to global knowledge.", "correct_answer": "D", "topic": "Friedman's Flatteners: In-forming", "solution": "In-forming (Flattener #10) is exemplified by search engines like Google and digital libraries, empowering individuals to build their own supply chain of information, knowledge, and entertainment.", "source_pdf_page": 39}];
